$ErrorActionPreference = "Stop"

$root = Split-Path -Parent $PSScriptRoot
$utf8 = New-Object System.Text.UTF8Encoding($false)

function Decode([string]$Value) {
    return [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Value))
}

$sql = Decode ""

$migration96 = Join-Path $root "supabase\migrations\20260812223200_klyx_group_atomic_live_coverage_12_96.sql"
$offerRoute = Join-Path $root "app\api\market\requests\[id]\offers\route.ts"
$jobsRoute = Join-Path $root "app\api\provider\jobs\route.ts"
$jobsHelper = Join-Path $root "lib\provider-jobs-live-revalidation.ts"
$migrationPath = Join-Path $root "supabase\migrations\20260813105500_klyx_multi_slot_offer_atomic_13_09.sql"

foreach ($path in @($migration96, $offerRoute, $jobsRoute, $jobsHelper)) {
    if (-not (Test-Path -LiteralPath $path)) {
        throw "13.09 : fichier requis introuvable : $path"
    }
}

$sql96 = [System.IO.File]::ReadAllText($migration96)
$offer = [System.IO.File]::ReadAllText($offerRoute)
$jobs = [System.IO.File]::ReadAllText($jobsRoute)
$helper = [System.IO.File]::ReadAllText($jobsHelper)

if (-not $sql96.Contains("KLYX_GROUP_ATOMIC_LIVE_COVERAGE_12_96")) {
    throw "13.09 : KLYX 12.96 introuvable."
}

if (-not $sql96.Contains("klyx_group_live_coverage_check")) {
    throw "13.09 : RPC live coverage introuvable."
}

if (-not $offer.Contains("KLYX_MULTI_SLOT_LIVE_OFFER_GUARD_12_95")) {
    throw "13.09 : garde API 12.95 introuvable."
}

if (-not $jobs.Contains("KLYX_PROVIDER_JOBS_LIVE_ROUTE_13_08")) {
    throw "13.09 : KLYX 13.08 route introuvable."
}

if (-not $helper.Contains("KLYX_PROVIDER_JOBS_LIVE_ELIGIBILITY_13_08")) {
    throw "13.09 : KLYX 13.08 helper introuvable."
}

if (Test-Path -LiteralPath $migrationPath) {
    $existing = [System.IO.File]::ReadAllText($migrationPath)

    if (-not $existing.Contains("KLYX_MULTI_SLOT_OFFER_ATOMIC_GUARD_13_09")) {
        throw "13.09 : migration existante inattendue."
    }

    Write-Host "Migration 13.09 deja presente."
}
else {
    [System.IO.File]::WriteAllText($migrationPath, $sql, $utf8)
}

Write-Host ""
Write-Host "======================================"
Write-Host "KLYX 13.09 PREPARE"
Write-Host "======================================"
Write-Host "Offre multi-slot : GARDE DB ATOMIQUE"
Write-Host "Couverture : N/N OBLIGATOIRE"
Write-Host "TOCTOU API : FERME"
Write-Host "Mission simple : INCHANGEE"
Write-Host "Offre automatique : NON"
Write-Host "Booking automatique : NON"
Write-Host "Paiement automatique : NON"
Write-Host "======================================"
